# Guest-side trampolines (32-bit compat code) + park routine (64-bit). Assembled to a blob loaded at TB=0x0F000000.
# layout: 0x0000 64-bit code (enter32 is generated by host.c at 0x100, Lpark64 here at 0x300)
#         0x1000 data page (cs32@0 ds32@8 park_fn@16)
#         0x2000 32-bit code
.intel_syntax noprefix
.set TB, 0x0F000000
.set PARK64, TB+0x300
.set WAIT, TB+0x2100
.text
.code64
.org 0x300
Lpark64:
  mov r13d, ecx
  mov rsp, [r13]
  cld
  mov rdi, r13
  mov rax, qword ptr [0x0F001010]
  call rax
  mov ecx, r13d
  .byte 0x41, 0xff, 0x6d, 0x68
.code32
.org 0x2000
Ltramp32:
  push ecx
  mov ecx, esp
  or ecx, 0x7fffff
  inc ecx
  sub ecx, 0x400
  mov [ecx+0x3c], eax
  pop eax
  mov [ecx+0x0c], eax
  mov [ecx+0x10], edx
  mov [ecx+0x14], ebx
  mov [ecx+0x18], esp
  mov [ecx+0x1c], ebp
  mov [ecx+0x20], esi
  mov [ecx+0x24], edi
Lpost:
  mov dword ptr [ecx+0x58], 1
  jmp Lwait
.org 0x2100
Lwait:
  mov edx, 1800000000
1:
  cmp dword ptr [ecx+0x58], 2
  je Lgo
  pause
  dec edx
  jnz 1b
  jmp Lwait
Lgo:
  mov eax, [ecx+0x08]
  mov edx, [ecx+0x10]
  mov ebx, [ecx+0x14]
  mov ebp, [ecx+0x1c]
  mov esi, [ecx+0x20]
  mov edi, [ecx+0x24]
  test dword ptr [ecx+0x38], 1
  jz 2f
  fld qword ptr [ecx+0x30]
2:
  mov esp, [ecx+0x18]
  cmp dword ptr [ecx+0x5c], 1
  je Lkret4
  ja Lkjmp
  mov ecx, [ecx+0x0c]
  ret
Lkret4:
  mov ecx, [ecx+0x0c]
  ret 4
Lkjmp:
  push dword ptr [ecx+0x28]
  mov ecx, [ecx+0x0c]
  ret
.org 0x2200
Ldone32:
  mov ecx, esp
  or ecx, 0x7fffff
  inc ecx
  sub ecx, 0x400
  mov [ecx+0x08], eax
  mov [ecx+0x10], edx
  cmp dword ptr [ecx+0x54], 0
  je 3f
  fstp qword ptr [ecx+0x30]
3:
  mov dword ptr [ecx+0x3c], 0xffffff
  jmp Lpost
.org 0x2300
Lpad_entry:
  call eax
  jmp Ldone32
